        cutoff = timezone.now() - timezone.timedelta(days=days)
        return self.filter(last_login_at__lt=cutoff, is_active=False)

    def hard_delete(self):
        total = 0
        for customer in self.iterator():
            total += customer.delete()[0]
        return total, self.model

    def anonymise(self):
        return self.update(
            full_name='',
            email='',
            phone='',
            anonymised_at=timezone.now(),
        )


