class Command(BaseCommand):
    help = 'Hard delete customers past the retention window'

    def add_arguments(self, parser):
        parser.add_argument('--days', type=int, default=MIN_RETENTION_DAYS)

    def handle(self, *args, **options):
        days = options['days']
        if days < MIN_RETENTION_DAYS:
            raise CommandError(
                'retention window must be at least %s days' % MIN_RETENTION_DAYS
            )
        queryset = Customer.objects.inactive_since(days)
        count = queryset.count()
        self.stdout.write('candidates=%s window_days=%s' % (count, days))
        for customer in queryset.iterator():
            customer.delete()
        self.stdout.write(self.style.SUCCESS('purged=%s' % count))

