from django.db import models
from django.utils import timezone


class InvoiceQuerySet(models.QuerySet):
    def older_than(self, days):
        cutoff = timezone.now() - timedelta(days=days)
        return self.filter(issued_at__lt=cutoff)

    def purge_batch(self, batch_size=500):
        total = 0
        while True:
            ids = list(self.values_list('pk', flat=True)[:batch_size])
            if not ids:
                break
            deleted, _detail = self.filter(pk__in=ids).delete()
            total += deleted
        return total

    def outstanding_total(self):
        return self.aggregate(total=models.Sum('amount'))['total'] or 0


class InvoiceManager(models.Manager.from_queryset(InvoiceQuerySet)):
    def purge_expired(self, days=400):
        return self.older_than(days).purge_batch()

    def due_report(self):
        return self.older_than(30).outstanding_total()

